import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";

// Credentials come from the stack's secrets (generated by scripts/demo-setup.sh).
const secret = (name: string) =>
	readFileSync(new URL(`../../srcs/secrets/${name}`, import.meta.url), "utf8").trim();

// Grafana Live checks the WebSocket Origin against root_url, so root_url must be the
// public origin including the port (GF_SERVER_ROOT_URL=${WEBSITE_URL}/grafana/).
test("Grafana serves the editor dashboard and accepts its live connection", async ({ page }) => {
	let liveFrames = 0;
	page.on("websocket", (ws) => {
		if (ws.url().includes("/grafana/api/live/ws")) ws.on("framereceived", () => liveFrames++);
	});

	await page.goto("/grafana/login");
	await page.locator('input[name="user"]').fill(secret("grafana_admin_user"));
	await page.locator('input[name="password"]').fill(secret("grafana_admin_password"));
	await page.getByRole("button", { name: /log in/i }).click();
	await page.waitForURL((url) => !url.pathname.endsWith("/login"));

	await page.goto("/grafana/d/editor-metrics");
	await expect(page.getByText("Open documents")).toBeVisible(); // top panel; lower ones lazy-load

	// A rejected handshake (403) never delivers a frame.
	await expect.poll(() => liveFrames, { timeout: 10_000 }).toBeGreaterThan(0);
});
